mapper.update:
UPDATE tasks
SET status = #{toStatus},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND status = #{fromStatus}

UPDATE tasks
SET provider_id = #{providerId},
    status = 'ACCEPTED',
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND requester_id = #{requesterId}
  AND status = 'OPEN'
  AND provider_id IS NULL

mapper.select:
SELECT * FROM tasks


    AND (title LIKE CONCAT('%', #{keyword}, '%') OR description LIKE CONCAT('%', #{keyword}, '%'))


    AND category = #{category}


    AND campus = #{campus}


    AND status = #{status}


    AND reward_type = #{rewardType}


    AND requires_proof = #{requiresProof}




    ORDER BY deadline ASC


    ORDER BY deadline DESC


    ORDER BY created_at DESC


    ORDER BY created_at DESC


LIMIT #{limit} OFFSET #{offset}

SELECT * FROM tasks t
WHERE t.status = #{status}
  AND (
    (#{status} = 'OPEN' AND t.deadline <= #{referenceTime})
    OR (#{status} = 'PENDING_CONFIRMATION' AND t.updated_at <= #{referenceTime})
  )
  AND NOT EXISTS (
    SELECT 1 FROM task_histories h
    WHERE h.task_id = t.id
      AND h.note = #{reminderNote}
  )
ORDER BY t.updated_at ASC, t.id ASC
LIMIT #{limit}

SELECT * FROM tasks t
WHERE t.status = #{status}
  AND EXISTS (
    SELECT 1 FROM task_histories h
    WHERE h.task_id = t.id
      AND h.note = #{reminderNote}
      AND h.created_at <= #{reminderCreatedBefore}
  )
ORDER BY t.updated_at ASC, t.id ASC
LIMIT #{limit}
